/**
 * T11 (Fix E, v0.7.3), back-compat half: manifests written BEFORE v0.7.3 render
 * byte-for-byte as they did before the per-model report lines existed.
 *
 * Every v0.7.3 line (By model, billed but not logged, the floor note, custom
 * price, unpriced, attribution, the receipt-booked labels) is keyed on a field
 * the v0.7.2 collector never wrote, so a report over an older run must not
 * change by a single character. The goldens in
 * tools/test/fixtures/report-old-manifests/<case>/expected.{txt,md} were
 * generated by tools/report.mjs as it stood before this change (branch base
 * 7df9cc9 plus a comment-only edit), over manifests and orchestrator events
 * written by the v0.7.2 collector itself (see that folder's README).
 *
 * Paths vary per machine, so the pass directory sits at
 * <tmp>/examples/study/passes/pass1 and every occurrence of <tmp> is replaced
 * by <ROOT> before comparing. The report's project root is four levels up, a
 * fresh temp path, so no transcript directory matches under ~/.claude/projects
 * or $CLAUDE_CONFIG_DIR/projects and the Artifacts list is stable.
 *
 * Regenerate (only when an intended change to OLD-manifest output is made, and
 * say why in the commit): REPORT_GOLDEN_WRITE=1 node --test tools/test/report-old-manifests.test.mjs
 * $0, offline.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const REPORT = join(ROOT, "tools", "report.mjs");
const CASES_DIR = join(ROOT, "tools", "test", "fixtures", "report-old-manifests");
const WRITE = process.env.REPORT_GOLDEN_WRITE === "1";

/**
 * Each case names its manifest and the telemetry files concatenated in order,
 * relative to the case folder, so the receivables-ops telemetry is reused
 * rather than copied.
 */
const CASES = JSON.parse(readFileSync(join(CASES_DIR, "cases.json"), "utf8"));

function render(spec, markdown) {
  const tmp = mkdtempSync(join(tmpdir(), "report-old-"));
  try {
    const passDir = join(tmp, "examples", "study", "passes", "pass1");
    mkdirSync(passDir, { recursive: true });
    const caseDir = join(CASES_DIR, spec.name);
    writeFileSync(join(passDir, "manifest.json"), readFileSync(join(caseDir, spec.manifest)));
    const lines = spec.telemetry.flatMap((f) => readFileSync(join(caseDir, f), "utf8").split("\n").filter((l) => l.trim()));
    writeFileSync(join(passDir, "telemetry.jsonl"), lines.join("\n") + "\n");
    const out = execFileSync("node", markdown ? [REPORT, passDir, "--markdown"] : [REPORT, passDir], { encoding: "utf8" });
    return out.split(tmp).join("<ROOT>");
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
}

for (const spec of CASES) {
  for (const markdown of [false, true]) {
    const golden = join(CASES_DIR, spec.name, markdown ? "expected.md" : "expected.txt");
    test(`old manifest renders exactly as before: ${spec.name}${markdown ? " (--markdown)" : ""}`, () => {
      const out = render(spec, markdown);
      if (WRITE) writeFileSync(golden, out);
      assert.equal(out, readFileSync(golden, "utf8"));
    });
  }
}
